import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"子夏易傳 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"子夏易傳 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"classics/zixia/028.md","filePath":"classics/zixia/028.md"}'),i={name:"classics/zixia/028.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><p>卦辭：大畜。利貞。不家食吉。利涉大川。</p><p>彖曰：大畜，剛健篤實，輝光日新其徳。剛上而尚賢，能止健大正也。不家食吉，養賢也。利涉大川，應乎天也。</p><p>子夏：剛健而上求於艮，非輝其光而日新其徳乎。剛上而尚賢，尊柔以奉之，重其徳，承其道也。能止健以為大正也。賢不肖，非其畜也。祿之以公食，勤之以民治，成上之功，畜而盡其能也。應乎天也。於何而不濟乎，是以利涉大川也。</p><p>象曰：天在山中，大畜。君子以多識，前言往行以畜其徳。</p><p>子夏：天在山中，小能畜大也。君子之畜大也。前言往行，多學而究之，論辨而擬之，以畜為徳也。</p><p>初九，有厲利已。</p><p>象曰：有厲利已，不犯災也。</p><p>子夏：上畜之初，何可自任，故居而待命則利往而違上，則厲也。</p><p>九二，輿説輹。</p><p>象曰：輿説輹，中無尤也。</p><p>子夏：大畜之下體為上之畜履無位，應中安其所畜，故脫輿輹而不往任上之畜也，終無尤也。</p><p>九三，良馬逐，利艱貞。曰：閑輿衛，利有攸往。</p><p>象曰：利有攸往，上合志也。</p><p>子夏：奉上之勞而不敢自獲，其志至終得治，則因其道焉。故開國承家，其道自利，馳良馬也。自任不可以縱緩，則失矣。艱而守正，乃利閑。習乘輿備其左右，則利有攸往矣。上大畜之終，則盛大矣，無不通也。習輿備衛所以合上之志，而皆通也。</p><p>六四，童牛之牿。元吉。</p><p>象曰：六四元吉，有喜也。</p><p>子夏：牛，陰類也，而又童焉，居牢而安能止其健，不勞其備而得其用，則何往而不濟焉。故大吉有喜也。</p><p>六五，豶豕之牙吉。</p><p>象曰：六五之吉有慶也。</p><p>子夏：四止於初，童牛而喜，不勞而得下之效也。至於五，下則剛長，事斯大矣，故有備而勞及獲其用也。其吉於豶豕之牙焉，豶豕，豭之無陽者，牙劣而不用可也。以大中而獲乾也。事之大濟，故有慶也。</p><p>上九，何天之衢，亨。</p><p>象曰：何天之衢道大行也。</p><p>子夏：大畜，冀其成也。剛上也。為柔上之，佐時行道，止健而致於治也。既成而大通矣，於何往而不可哉。故上九曰何以為也。雖天衢而通也，可謂大行也已矣。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
